#[derive(Debug)]
enum Vehicle {
    Bike,
    Car,
    Truck(u32), // the number of axles
}

struct Ticket {
    vehicle: Vehicle,
    hours: u32,
}

fn hourly_rate(vehicle: &Vehicle) -> u32 {
    match vehicle {
        Vehicle::Bike => 1,
        Vehicle::Car => 3,
        Vehicle::Truck(axles) if *axles >= 4 => 20,
        Vehicle::Truck(axles) => 5 * axles,
    }
}

impl Ticket {
    fn cost(&self) -> u32 {
        hourly_rate(&self.vehicle) * self.hours
    }
}

fn most_expensive(tickets: &[Ticket]) -> Option<u32> {
    let mut best = None;
    for ticket in tickets {
        let cost = ticket.cost();
        match best {
            Some(b) if b >= cost => {}
            _ => best = Some(cost),
        }
    }
    best
}

fn main() {
    let tickets = [
        Ticket { vehicle: Vehicle::Bike, hours: 4 },
        Ticket { vehicle: Vehicle::Car, hours: 2 },
        Ticket { vehicle: Vehicle::Truck(2), hours: 3 },
        Ticket { vehicle: Vehicle::Truck(5), hours: 1 },
    ];
    for t in &tickets {
        println!("{:?}: {} per hour, {} in total", t.vehicle, hourly_rate(&t.vehicle), t.cost());
    }
    println!("{:?}", most_expensive(&tickets));
    println!("{:?}", most_expensive(&tickets[..1]));
    println!("{:?}", most_expensive(&tickets[..0]));
}
